// src/store/newsReducer.ts
import { fetchNews } from '../services/newsService';

// ✅ Define State Interface
export interface NewsState {
  articles: any[];
  status: 'idle' | 'loading' | 'succeeded' | 'failed';
  source: string;
  date: string;
  category: string;
  author: string;
  query: string;
}

// ✅ Initial State
const initialState: NewsState = {
  articles: [],
  status: 'idle',
  source: 'newsapi',
  date: '',
  category: '',
  author: '',
  query: '',
};

// ✅ Define Action Types
const FETCH_ARTICLES_REQUEST = 'FETCH_ARTICLES_REQUEST';
const FETCH_ARTICLES_SUCCESS = 'FETCH_ARTICLES_SUCCESS';
const FETCH_ARTICLES_FAILURE = 'FETCH_ARTICLES_FAILURE';
const SET_FILTERS = 'SET_FILTERS';

// ✅ Reducer Function
const newsReducer = (state = initialState, action: any): NewsState => {
  switch (action.type) {
    case FETCH_ARTICLES_REQUEST:
      return { ...state, status: 'loading' };
    case FETCH_ARTICLES_SUCCESS:
      return { ...state, status: 'succeeded', articles: action.payload };
    case FETCH_ARTICLES_FAILURE:
      return { ...state, status: 'failed' };
    case SET_FILTERS:
      return { ...state, ...action.payload };
    default:
      return state;
  }
};

// ✅ Define Action Creators
export const fetchArticles = ({ query, source, date, category, author }: Partial<NewsState>) => {
  return async (dispatch: any) => {
    dispatch({ type: FETCH_ARTICLES_REQUEST });

    try {
      const response = await fetchNews(query || 'latest', source || 'newsapi', date || '', category || '', author || '');
      dispatch({ type: FETCH_ARTICLES_SUCCESS, payload: response.articles || response.response?.docs || response.response?.results });
    } catch (error) {
      dispatch({ type: FETCH_ARTICLES_FAILURE });
    }
  };
};

export const setFilters = (filters: Partial<NewsState>) => ({
  type: SET_FILTERS,
  payload: filters,
});

export default newsReducer;
